const customSignToggle = localStorage.getItem('ai-custom-fallback-sign-toggle') === 'true';
const customSignText = localStorage.getItem('ai-custom-fallback-sign-text') || '∞';
const defaultSign = customSignToggle ? customSignText : '∞';

const bookmarks = getBookmarkedModels();
Array.from(sel.options).forEach(opt => {
    const div = document.createElement('div');
    div.className = 'ai-dd-opt';
    div.dataset.val = opt.value;
    div.style.cssText = 'padding:8px 12px; font-size:0.78rem; color:var(--text-primary); cursor:pointer; display:flex; justify-content:space-between; align-items:center; border-bottom: 1px solid rgba(255,255,255,0.03);';

    const isBookmarked = bookmarks.includes(opt.value);
    const labelSpan = document.createElement('span');
    labelSpan.textContent = (isBookmarked ? '★ ' : '') + opt.text;
    div.appendChild(labelSpan);

    const rightContainer = document.createElement('div');
    rightContainer.style.cssText = 'display:flex; align-items:center; gap:6px;';

    const spec = getModelSpec(provider, opt.value) || {};
    const usage = getCalculatedUsage(provider, opt.value);

    const parseLimitVal = (val) => {
        if (!val) return 0;
        if (typeof val === 'number') return val;
        const clean = String(val).toUpperCase().trim();
        if (clean === 'UNLIMITED' || clean === '-') return Infinity;
        const num = parseFloat(clean);
        if (isNaN(num)) return 0;
        if (clean.includes('K')) return num * 1000;
        if (clean.includes('M')) return num * 1000000;
        return num;
    };

    const limitRPD = parseLimitVal(spec.rpd);

    let pctText = defaultSign;
    let pctColor = 'var(--text-muted)';
    let pctBg = 'rgba(255,255,255,0.05)';

    if (limitRPD && limitRPD !== Infinity && limitRPD > 0) {
        const used = usage.requestsLastDay || 0;
        const pct = Math.max(0, Math.min(100, Math.round(((limitRPD - used) / limitRPD) * 100)));
        pctText = `${pct}%`;
        if (pct > 50) {
            pctColor = '#10b981';
            pctBg = 'rgba(16, 185, 129, 0.15)';
        } else if (pct >= 10) {
            pctColor = '#f59e0b';
            pctBg = 'rgba(245, 158, 11, 0.15)';
        } else {
            pctColor = '#f87171';
            pctBg = 'rgba(248, 113, 113, 0.15)';
        }
