function populateGitAIModelDropdown() {
    const sel = document.getElementById('git-ai-model-select');
    if (!sel) return;
    sel.innerHTML = '';

    // Use the same dynamic model list as the AI copilot (Gemini models)
    const models = (typeof DYNAMIC_AI_MODELS !== 'undefined' && DYNAMIC_AI_MODELS['gemini'])
        ? DYNAMIC_AI_MODELS['gemini']
        : [
            { val: 'gemini-2.5-flash', label: 'Gemini 2.5 Flash' },
            { val: 'gemini-2.0-flash', label: 'Gemini 2.0 Flash' },
            { val: 'gemini-1.5-flash', label: 'Gemini 1.5 Flash' },
            { val: 'gemini-2.5-pro',   label: 'Gemini 2.5 Pro' },
            { val: 'gemini-1.5-pro',   label: 'Gemini 1.5 Pro' }
        ];

    models.forEach(m => {
        const opt = document.createElement('option');
        opt.value = m.val;
        opt.textContent = m.label || m.val;
        sel.appendChild(opt);
    });

    // Restore previously selected model, fall back to copilot selection, then default
    const saved = localStorage.getItem('git-ai-commit-model');
    const copilotModel = localStorage.getItem('ai-model-gemini') || 'gemini-2.5-flash';
    const preferred = saved || copilotModel;
    if (models.some(m => m.val === preferred)) {
        sel.value = preferred;
    } else if (models.length > 0) {
        sel.value = models[0].val;
    }

    // Persist selection changes
    sel.onchange = () => localStorage.setItem('git-ai-commit-model', sel.value);
}

async function suggestGitCommitMessage() {
    const btn = document.getElementById('git-ai-suggest-btn');
    const iconEl = document.getElementById('git-ai-suggest-icon');
    const statusEl = document.getElementById('git-status-msg');
    const textarea = document.getElementById('git-commit-msg');

    const apiKey = localStorage.getItem('gemini-api-key') || '';
    if (!apiKey) {
        statusEl.style.color = '#ef4444';
        statusEl.innerText = 'No Gemini API key found. Add it in AI Copilot settings.';
        setTimeout(() => { statusEl.innerText = ''; statusEl.style.color = 'var(--text-secondary)'; }, 4000);
        return;
    }

    const modelSel = document.getElementById('git-ai-model-select');
    const model = (modelSel && modelSel.value) ? modelSel.value : 'gemini-2.5-flash';

    // Show loading state on button
    btn.disabled = true;
    iconEl.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="animation:spin 0.8s linear infinite;"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>';
    statusEl.style.color = 'var(--text-secondary)';
    statusEl.innerText = 'Analyzing changes with AI...';

    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/suggest-commit`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ api_key: apiKey, model: model })
        });
        const data = await res.json();

        if (!res.ok || data.error) {
            statusEl.style.color = '#ef4444';
            statusEl.innerText = data.error || 'AI suggestion failed.';
            setTimeout(() => { statusEl.innerText = ''; statusEl.style.color = 'var(--text-secondary)'; }, 5000);
            return;
        }

        if (data.suggestion) {
            textarea.value = data.suggestion;
            textarea.style.borderColor = 'var(--accent-color)';
            setTimeout(() => { textarea.style.borderColor = 'var(--border-color)'; }, 1500);
            statusEl.style.color = '#22c55e';
            statusEl.innerText = 'AI commit message filled ✓';
            setTimeout(() => { statusEl.innerText = ''; statusEl.style.color = 'var(--text-secondary)'; }, 3000);
        }
    } catch (e) {
        statusEl.style.color = '#ef4444';
        statusEl.innerText = 'Request failed: ' + e.message;
        setTimeout(() => { statusEl.innerText = ''; statusEl.style.color = 'var(--text-secondary)'; }, 5000);
    } finally {
        btn.disabled = false;
        iconEl.textContent = '✨';
    }
}

