function getTesterIgnoredModels() {
    try {
        return JSON.parse(localStorage.getItem('ai-tester-ignored-models')) || { gemini: [], groq: [], morph: [], openrouter: [] };
    } catch(e) {
        return { gemini: [], groq: [], morph: [], openrouter: [] };
    }
}

function saveTesterIgnoredModels(ignored) {
    localStorage.setItem('ai-tester-ignored-models', JSON.stringify(ignored));
}

function _isModelTesterIgnored(modelVal) {
    const provider = activeFilterTab || 'gemini';
    const ignored = getTesterIgnoredModels();
    return (ignored[provider] || []).includes(modelVal);
}

function _toggleTesterModelIgnore(modelVal) {
    const provider = activeFilterTab || 'gemini';
    const ignored = getTesterIgnoredModels();
    if (!ignored[provider]) ignored[provider] = [];
    const idx = ignored[provider].indexOf(modelVal);
    if (idx >= 0) {
        ignored[provider].splice(idx, 1);
    } else {
        ignored[provider].push(modelVal);
    }
    saveTesterIgnoredModels(ignored);
    const card = document.querySelector(`#model-tester-results [data-model="${modelVal}"]`);
    if (card) {
        const ignoreBtn = card.querySelector('.tester-ignore-btn');
        if (ignoreBtn) {
            const isNowIgnored = ignored[provider].includes(modelVal);
            const svgPlay = '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
            const svgPause = '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>';
            ignoreBtn.innerHTML = isNowIgnored ? svgPause : svgPlay;
            ignoreBtn.title = isNowIgnored ? 'Model skipped in tests — click to include' : 'Model included in tests — click to skip';
            ignoreBtn.style.opacity = isNowIgnored ? '0.5' : '1';
        }
    }
}

function _isModelHidden(modelVal) {
    const provider = activeFilterTab || 'gemini';
    const hidden = getHiddenModels();
    return (hidden[provider] || []).includes(modelVal);
}

function _toggleTesterModelVisibility(modelVal) {
    const provider = activeFilterTab || 'gemini';
    const hidden = getHiddenModels();
    if (!hidden[provider]) hidden[provider] = [];
    const idx = hidden[provider].indexOf(modelVal);
    if (idx >= 0) {
        hidden[provider].splice(idx, 1);
    } else {
        hidden[provider].push(modelVal);
    }
    saveHiddenModels(hidden);
    // Update the eye icon in-place
    const card = document.querySelector(`#model-tester-results [data-model="${modelVal}"]`);
    if (card) {
        const eyeBtn = card.querySelector('.tester-eye-btn');
        if (eyeBtn) {
            const isNowHidden = hidden[provider].includes(modelVal);
            eyeBtn.innerHTML = isNowHidden ? '🚫' : '👁️';
            eyeBtn.title = isNowHidden ? 'Model hidden — click to show' : 'Model visible — click to hide';
            eyeBtn.style.opacity = isNowHidden ? '0.5' : '1';
        }
    }
    // Sync filter modal list if open
    if (typeof renderFilterModelsList === 'function') renderFilterModelsList();
    // Sync the model dropdown in copilot
    if (typeof handleAIProviderChange === 'function') handleAIProviderChange();
}

function _renderTesterCard(model, status, detail, timeMs) {
    const isHidden = _isModelHidden(model.val);

    // Define standard color base
    const statusColors = {
        pending: { bg: 'rgba(100,116,139,0.12)', border: '#475569', icon: '⏳', color: '#94a3b8' },
        running: { bg: 'rgba(59,130,246,0.12)', border: '#3b82f6', icon: '⏳', color: '#60a5fa' },
        success: { bg: 'rgba(16,185,129,0.1)', border: '#10b981', icon: '✅', color: '#34d399' },
        error:   { bg: 'rgba(239,68,68,0.1)', border: '#ef4444', icon: '❌', color: '#f87171' },
        skipped: { bg: 'rgba(100,116,139,0.05)', border: '#334155', icon: '⏭️', color: '#64748b' }
    };

    let s = statusColors[status] || statusColors.pending;

    // Apply Conflict Logic for visibility mismatches
    if (status === 'success' && isHidden) {
        // Works but is Hidden -> Cyan/Blue (Informational)
        s = { bg: 'rgba(6,182,212,0.15)', border: '#0891b2', icon: '✅', color: '#22d3ee' };
    } else if (status === 'error' && !isHidden) {
        // Fails but is Visible -> Orange/Gold (Warning)
        s = { bg: 'rgba(245,158,11,0.15)', border: '#d97706', icon: '⚠️', color: '#fbbf24' };
    }

    const timeStr = timeMs != null ? `${(timeMs / 1000).toFixed(2)}s` : '';
    const detailEscaped = (detail || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const truncatedDetail = detailEscaped.length > 200 ? detailEscaped.substring(0, 200) + '…' : detailEscaped;

    const eyeIcon = isHidden ? '🚫' : '👁️';
    const eyeTitle = isHidden ? 'Model hidden globally — click to show' : 'Model visible globally — click to hide';
    const eyeOpacity = isHidden ? '0.5' : '1';

    const svgPlay = '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" style="display:block;"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
    const svgPause = '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" style="display:block;"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>';

    const isIgnored = _isModelTesterIgnored(model.val);
    const ignoreIcon = isIgnored ? svgPause : svgPlay;
    const ignoreTitle = isIgnored ? 'Model skipped in tests — click to include' : 'Model included in tests — click to skip';
    const ignoreOpacity = isIgnored ? '0.5' : '1';

    const speeds = getModelSpeeds();
    const provider = activeFilterTab || 'gemini';
    const providerSpeeds = speeds[provider] || {};
    const currentSpeed = providerSpeeds[model.val] || 'Medium';

    const speedColors = { Fast: '#60a5fa', Medium: '#f59e0b', Slow: '#f87171', None: 'var(--text-secondary)' };
    const speedColor = speedColors[currentSpeed] || 'var(--text-primary)';

    const speedSelectHtml = `
        <select onchange="
            const val = this.value;
            const updatedSpeeds = getModelSpeeds();
            if (!updatedSpeeds['${provider}']) updatedSpeeds['${provider}'] = {};
            updatedSpeeds['${provider}']['${model.val}'] = val;
            saveModelSpeeds(updatedSpeeds);
            const colors = { Fast: '#60a5fa', Medium: '#f59e0b', Slow: '#f87171', None: 'var(--text-secondary)' };
            this.style.color = colors[val] || 'var(--text-primary)';
            if (typeof renderFilterModelsList === 'function') renderFilterModelsList();
        " style="background:var(--bg-main) url(&quot;data:image/svg+xml;utf8,<svg fill='%23a1a1aa' height='8' viewBox='0 0 24 24' width='8' xmlns='http://www.w3.org/2000/svg'><path d='M7 10l5 5 5-5z'/></svg>&quot;) no-repeat right 3px center; border:1px solid var(--border-color); border-radius:4px; font-size:0.64rem; padding:1px 11px 1px 3px; outline:none; cursor:pointer; width:58px; appearance:none; -webkit-appearance:none; font-weight:600; text-align-last: center; color:${speedColor}; margin-right:4px;">
            <option value="Fast" style="background:var(--bg-sidebar); color:#60a5fa;" ${currentSpeed === 'Fast' ? 'selected' : ''}>Fast</option>
            <option value="Medium" style="background:var(--bg-sidebar); color:#f59e0b;" ${currentSpeed === 'Medium' ? 'selected' : ''}>Med</option>
            <option value="Slow" style="background:var(--bg-sidebar); color:#f87171;" ${currentSpeed === 'Slow' ? 'selected' : ''}>Slow</option>
            <option value="None" style="background:var(--bg-sidebar); color:var(--text-secondary);" ${currentSpeed === 'None' ? 'selected' : ''}>None</option>
        </select>
    `;

    return `<div data-model="${model.val}" style="background:${s.bg}; border:1px solid ${s.border}; border-radius:6px; padding:8px 10px; display:flex; flex-direction:column; gap:3px;">
        <div style="display:flex; justify-content:space-between; align-items:center;">
            <span style="font-weight:600; font-size:0.75rem; color:var(--text-primary);">${s.icon} ${model.label}</span>
            <div style="display:flex; align-items:center; gap:8px;">
                <span style="font-size:0.68rem; color:${s.color}; font-weight:500;">${status === 'running' ? 'Testing...' : status === 'pending' ? 'Waiting' : status === 'skipped' ? 'Skipped' : timeStr}</span>

