    if (_modelTesterRunning) return;

    const provider = activeFilterTab || 'gemini';
    const prompt = document.getElementById('model-tester-prompt').value.trim();
    if (!prompt) {
        alert('Please enter a test prompt.');
        return;
    }

    const apiKey = provider === 'gemini'
        ? (localStorage.getItem('gemini-api-key') || '')
        : provider === 'morph'
        ? (localStorage.getItem('morph-api-key') || '')
        : provider === 'openrouter'
        ? (localStorage.getItem('openrouter-api-key') || '')
        : (localStorage.getItem('groq-api-key') || '');

    if (!apiKey) {
        alert(`No API key configured for ${AI_PROVIDER_LABELS[provider]}. Please set it in the AI Copilot settings.`);
        return;
    }

    const models = getMergedAIModels(provider);
    if (!models || models.length === 0) {
        alert('No models found for this provider.');
        return;
    }

    _modelTesterAbort = false;
    _modelTesterRunning = true;

    const runBtn = document.getElementById('model-tester-run-btn');
    const stopBtn = document.getElementById('model-tester-stop-btn');
    const statusEl = document.getElementById('model-tester-status');
    const counterEl = document.getElementById('model-tester-counter');
    const resultsEl = document.getElementById('model-tester-results');

    runBtn.style.display = 'none';
    stopBtn.style.display = 'inline-flex';

    // Render all cards as pending
    resultsEl.innerHTML = models.map(m => _renderTesterCard(m, 'pending', '', null)).join('');

    let passed = 0, failed = 0;

    for (let i = 0; i < models.length; i++) {
        if (_modelTesterAbort) break;

        const model = models[i];

        if (_isModelTesterIgnored(model.val)) {
            const cardEl = resultsEl.querySelector(`[data-model="${model.val}"]`);
            if (cardEl) {
                cardEl.outerHTML = _renderTesterCard(model, 'skipped', 'Skipped by user', null);
            }
            continue;
        }

        statusEl.textContent = `Testing ${i + 1} of ${models.length}: ${model.label}...`;
        counterEl.textContent = `${passed} ✅  ${failed} ❌  (${i}/${models.length})`;

        // Update this card to "running"
        const cardEl = resultsEl.querySelector(`[data-model="${model.val}"]`);
        if (cardEl) {
            cardEl.outerHTML = _renderTesterCard(model, 'running', '', null);
        }

        const startTime = performance.now();
        try {
            const res = await fetch('/api/ai-command', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    prompt: prompt,
                    api_key: apiKey,
                    provider: provider,
                    model: model.val,
                    system_instruction: '',
                    history: []
                })
            });
            const elapsed = performance.now() - startTime;
            const data = await res.json();

            const updatedCard = resultsEl.querySelector(`[data-model="${model.val}"]`);
            if (!res.ok) {
                failed++;
                if (updatedCard) updatedCard.outerHTML = _renderTesterCard(model, 'error', data.error || `HTTP ${res.status}`, elapsed);
            } else {
                passed++;
                const reply = data.command || data.text || '(empty response)';
                if (updatedCard) updatedCard.outerHTML = _renderTesterCard(model, 'success', reply, elapsed);
            }
        } catch (err) {
            const elapsed = performance.now() - startTime;
            failed++;
            const updatedCard = resultsEl.querySelector(`[data-model="${model.val}"]`);
            if (updatedCard) updatedCard.outerHTML = _renderTesterCard(model, 'error', err.message, elapsed);
        }
    }

    const totalTested = passed + failed;
    counterEl.textContent = `${passed} ✅  ${failed} ❌  (${totalTested}/${models.length})`;
    statusEl.textContent = _modelTesterAbort ? 'Stopped by user' : 'Complete';
    runBtn.style.display = 'inline-flex';
    stopBtn.style.display = 'none';
    _modelTesterRunning = false;
}

function selectAIProvider(val) {
    document.getElementById('ai-provider-select').value = val;
    document.getElementById('ai-provider-dd-menu').style.display = 'none';
    document.removeEventListener('click', _aiProviderOutside);

    handleAIProviderChange();
    refreshAIProviderLabels();
    fetchDynamicModels(val);
}

