            const opt = document.createElement('option');
            opt.value = m.val;
            opt.textContent = m.label || m.val;
            sel.appendChild(opt);
        });
        // Restore preference: saved > copilot selection > first
        const saved = localStorage.getItem('git-ai-commit-model');
        const copilot = localStorage.getItem('ai-model-gemini') || 'gemini-2.5-flash';
        const preferred = saved || copilot;
        if (models.some(m => m.val === preferred)) {
            sel.value = preferred;
        } else if (prev && models.some(m => m.val === prev)) {
            sel.value = prev;
        } else if (models.length > 0) {
            sel.value = models[0].val;
        }
        sel.onchange = () => localStorage.setItem('git-ai-commit-model', sel.value);
    }

    // Use already-loaded dynamic list if available
    const dynamic = (typeof DYNAMIC_AI_MODELS !== 'undefined') ? (DYNAMIC_AI_MODELS['gemini'] || []) : [];
